import React from "react";
import Categories from "../home-page/categories";
import getAllTourCategories from "@/services/getTourCategories";

const amounts = [
  {
    tier: "Explore",
    price: "$100",
    body: "Skip the socks! Let friends and family contribute to your dream trip instead!",
    popular: false,
  },
  {
    tier: "Voyager",
    price: "$1,000",
    body: "Contribute to a cherished one's epic journey with a meaningful boost.",
    popular: true,
  },
  {
    tier: "Odyssey",
    price: "$10,000",
    body: "Gift a luxury experience, creating memories to last a lifetime.",
    popular: false,
  },
];

const steps = [
  {
    title: "Choose Your Card",
    body: "Select the amount you want to gift to your loved one.",
  },
  {
    title: "Add A Gift Message",
    body: "Personalize your gift with a message to your loved one.",
  },
  {
    title: "Send to yourself or directly to the recipient",
    body: "Send the gift card to yourself to print and gift physically, or send it directly to the recipient. You can schedule a date or send it immediately — great for those oops moments when you forget a birthday or anniversary!",
  },
];

const faqs: { q: string; a: React.ReactNode }[] = [
  {
    q: "Why should I join the TravelShop Booking marketplace?",
    a: "TSB has hundreds of suppliers from all around the world and new ones join every day. Plus the pages already house 10,000 tours and 350+ destinations. So there is too much to discover.",
  },
  {
    q: "What are my advantages going to be?",
    a: "Save 2% for 75.000 € up to 149.999 € booking, 5% for 150.000 up to 299.999 € booking, and 10% over 300.000 € and more booking.",
  },
  {
    q: "What is the TSG Operator Credit System?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-3">
          TravelShop Booking is aware that you, as our tour operators, work so
          hard to inspire travelers and make their experiences remarkable. We
          created this credit program to promote your efforts.
        </p>
        <strong className="tw-text-[#14101c]">Terms and Conditions:</strong>
        <ol className="tw-mt-2 tw-pl-5 tw-space-y-1.5">
          <li>
            Every operator is included in the credit program automatically when
            they register on the TravelShop Booking website.
          </li>
          <li>
            30 euros are defined for every operator&apos;s account automatically
            when they register.
          </li>
          <li>
            Operators gain credits from their sales at the rates below:
            <ol type="a" className="tw-mt-1.5 tw-pl-5 tw-space-y-1">
              <li>Save 2% for 75.000 € up to 149.999 booking</li>
              <li>Save 5% for 150.000 up to 299.999 € booking</li>
              <li>Save 10% over 300.000 € and more booking</li>
            </ol>
          </li>
          <li>All shopping must be done on the travelshopbooking.com website.</li>
          <li>
            In the credit program, one year is defined as January 1 to December
            31. Credit must be spent within one year of receiving it.
          </li>
          <li>
            TSB does not pay the credit amount in cash. Instead, the operator can
            book a TSB tour to Turkey destinations with the credit as a discount.
          </li>
          <li>Credit rates are not applicable to discounted tours.</li>
          <li>TSB Group reserves the right to make changes to the campaign.</li>
        </ol>
      </>
    ),
  },
  {
    q: "Will I pay for registration?",
    a: "No. It is all free and always will be.",
  },
  {
    q: "What should I do if I have any trouble at any level?",
    a: (
      <>
        Write to us via:{" "}
        <a
          href="mailto:operatorhelp@travelshopbooking.com"
          className="tw-font-semibold tw-text-[#854ec9]"
        >
          operatorhelp@travelshopbooking.com
        </a>
      </>
    ),
  },
];

const GiftCardPage = async () => {
  const tourCategories = await getAllTourCategories();

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                TravelShop
              </span>
              <h1 className="tw-mt-2 tw-text-[clamp(36px,5.5vw,60px)] tw-font-bold tw-tracking-tight tw-leading-[1.02] tw-text-[#14101c] tw-m-0">
                Gift Card
              </h1>
              <p className="tw-mt-3 tw-text-[clamp(18px,2.2vw,24px)] tw-font-semibold tw-text-[#5d556c]">
                One Card, 1000+ Incredible Experiences
              </p>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Choose the perfect present for loved ones or help friends leap
                into their next adventure. With our travel gift cards, you&apos;re
                not just giving a gift — you&apos;re unlocking a world of
                experiences.
              </p>
              <div className="tw-mt-7 tw-flex tw-flex-wrap tw-items-center tw-gap-5">
                <a
                  href="/gift-card/custom-gift-card"
                  className="tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[16px] tw-px-7 tw-py-4 tw-rounded-full tw-no-underline tw-transition-colors"
                >
                  Buy A Gift Card Now <span aria-hidden="true">→</span>
                </a>
                <a
                  href="/turkey-tours"
                  className="tw-inline-flex tw-items-center tw-gap-1.5 tw-font-bold tw-text-[15px] tw-text-[#854ec9] tw-no-underline hover:tw-underline"
                >
                  Explore fantastic trips <span aria-hidden="true">→</span>
                </a>
              </div>
            </div>
            <div>
              <img
                src="/images/gift.jpg"
                alt="Travel gift card"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      <Categories tourCategories={tourCategories} />

      {/* Choose amount */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Choose Your Amount
            </h2>
            <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-[#6b6577] tw-max-w-[60ch] tw-mx-auto">
              Select a digital gift card and open the door to new adventures,
              cherished memories, or the ultimate travel experience for your
              friends, family and valued colleagues.
            </p>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6 tw-items-stretch">
            {amounts.map((card) => (
              <div
                key={card.tier}
                className={`tw-relative tw-flex tw-flex-col tw-rounded-2xl tw-border tw-border-solid tw-p-6 tw-text-center tw-transition-all tw-duration-200 ${
                  card.popular
                    ? "tw-border-[#854ec9] tw-bg-[#faf8ff] tw-shadow-lg md:tw--mt-3"
                    : "tw-border-[#ebe7f0] tw-bg-white hover:tw-shadow-lg"
                }`}
              >
                {card.popular && (
                  <span className="tw-absolute tw--top-3 tw-left-1/2 tw--translate-x-1/2 tw-rounded-full tw-bg-[#854ec9] tw-px-4 tw-py-1 tw-text-[12px] tw-font-bold tw-uppercase tw-tracking-wide tw-text-white">
                    Most popular
                  </span>
                )}
                <img
                  src="/images/giftcard.jpeg"
                  alt={`${card.tier} gift card`}
                  loading="lazy"
                  className="tw-w-3/4 tw-mx-auto tw-rounded-xl"
                />
                <b className="tw-mt-4 tw-text-[14px] tw-font-bold tw-uppercase tw-tracking-wide tw-text-[#16a34a]">
                  {card.tier}
                </b>
                <div className="tw-mt-1 tw-text-[32px] tw-font-bold tw-text-[#14101c]">
                  {card.price}
                </div>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c] tw-flex-1">
                  {card.body}
                </p>
                <a
                  href="/gift-card/custom-gift-card"
                  className="tw-mt-5 tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[14px] tw-px-5 tw-py-3 tw-rounded-full tw-no-underline tw-transition-colors"
                >
                  Buy {card.price} Gift Card
                </a>
              </div>
            ))}
          </div>
          <div className="tw-mt-10 tw-text-center">
            <a
              href="/gift-card/custom-gift-card"
              className="tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#14101c] hover:tw-bg-black tw-text-white tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
            >
              Or Choose a Custom Amount <span aria-hidden="true">→</span>
            </a>
          </div>
        </div>
      </section>

      {/* Unlock the world */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[420px_1fr] tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <img
                src="/images/Small_638258094160242020.jpg"
                alt="Gift card experience"
                loading="lazy"
                className="tw-mx-auto tw-w-full tw-max-w-[370px] tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div>
              <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Unlock The World With A Gift Card
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                With our travel gift cards, gifting is as simple as dreaming of the
                next destination.
              </p>
              <ol className="tw-mt-5 tw-m-0 tw-p-0 tw-list-none tw-space-y-4">
                {steps.map((step, i) => (
                  <li key={step.title} className="tw-flex tw-gap-4">
                    <span className="tw-flex tw-h-9 tw-w-9 tw-shrink-0 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9] tw-text-white tw-text-[15px] tw-font-bold">
                      {i + 1}
                    </span>
                    <div>
                      <p className="tw-m-0 tw-text-[16px] tw-font-bold tw-text-[#14101c]">
                        {step.title}
                      </p>
                      <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                        {step.body}
                      </p>
                    </div>
                  </li>
                ))}
              </ol>
              <a
                href="/gift-card/custom-gift-card"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Buy Gift Card Now <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[920px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-8">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Frequently asked questions
            </h2>
          </div>
          <div className="tw-space-y-3">
            {faqs.map((faq) => (
              <details
                key={faq.q}
                className="tw-group tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-px-6 tw-py-4 [&[open]]:tw-shadow-sm"
              >
                <summary className="tw-flex tw-cursor-pointer tw-items-center tw-justify-between tw-gap-4 tw-text-[16px] tw-font-semibold tw-text-[#14101c] tw-list-none marker:tw-hidden">
                  {faq.q}
                  <svg
                    viewBox="0 0 448 512"
                    width={16}
                    height={16}
                    fill="currentColor"
                    aria-hidden="true"
                    className="tw-shrink-0 tw-text-[#854ec9] tw-transition-transform group-open:tw-rotate-180"
                  >
                    <path d="M201.4 374.6c12.5 12.5 32.8 12.5 45.3 0l160-160c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L224 306.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l160 160z" />
                  </svg>
                </summary>
                <div className="tw-mt-3 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
                  {faq.a}
                </div>
              </details>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
};

export default GiftCardPage;
